# Joint physical issuer/cover states and capped covered-bond loss.
if(!exists('covered_bond_dual_recourse'))library(creditratingsystem)
structured_account_case<-function(template,pool_paths){
 args<-template;first<-pool_paths$cashflows[[1]];origin<-first$date;end<-tail(pool_paths$dates,1)[[1]];amount<-first$principal_available+first$interest_available+first$recovery_gross;args$as_of<-origin;args$scenario_contract$dates<-list(end);args$baseline_cashflows<-list(list(scenario_id='s',cashflow_id='cash',date=end,amount=amount));args$exposure_paths<-list(list(scenario_id='s',exposure_id='account',date=end,signed_replacement_mark=0));args$collateral_paths<-list(list(scenario_id='s',netting_set_id='net',date=end,known_at=origin,collateral_value=0,haircut=0));args$settlement_terms[[1]]$estate_delay_days<-0;args$settlement_terms[[1]]$collateral_delay_days<-0;args$settlement_terms[[1]]$replacement_cost<-0;args$settlement_terms[[1]]$replacement_delay_days<-0;args$party_default_paths<-list(list(scenario_id='s',default_group_id='bank',date=end,conditional_pd=1,default_channel='bank'));args$shared_innovations<-list(list(scenario_id='s',date=end,channel_id='bank',uniform=.5));do.call(stress_pool_counterparties,args)$value
}
run_covered_bond_products<-function(data=NULL,verify_reference=TRUE){
 if(is.null(data))data<-jsonlite::fromJSON(system.file('extdata/covered_bond_products.json',package='creditratingsystem'),simplifyVector=FALSE);out<-errors<-list()
 for(name in names(data$variants)){
 case<-data$variants[[name]];subjects<-do.call(build_rating_subjects,case$subject_input)$value;pool<-do.call(build_credit_asset_pool,case$pool_input)$value;args<-case$path_input;args$asset_pool<-pool;paths<-do.call(simulate_asset_pool,args)$value;p<-case$issuer_portfolio;graph<-do.call(build_entity_graph,p$graph_input);prepared<-prepare_credit_portfolio(p$positions,graph,p$default_group_policy,p$contract);issuer<-simulate_credit_portfolio(prepared,p$group_pds,p$dependence_contract,p$shared_innovations,p$conditional_loss_paths,levels=.5)$value;issuer_rows<-case$issuer_paths;for(i in seq_along(issuer_rows)){failed<-issuer$position_defaults[[i]][[1]];issuer_rows[[i]]['issuer_default_date']<-list(if(failed)paths$scenario_contract$dates[[1]]else NULL);issuer_rows[[i]]$extension_triggered<-name=='maturity_extension'&&failed};bond<-case$bond_contract;bond$innovation_hash<-paths$innovation_hash;covered<-covered_bond_dual_recourse(pool,paths,bond,issuer_rows)$value;performing<-paths;performing$cashflows<-Filter(function(r)r$scenario_id=='t',paths$cashflows);account<-structured_account_case(data$account_stress_template,performing);origin<-paths$origin;horizon<-as.numeric(as.Date(covered$horizon_end)-as.Date(origin));sampling<-list(contract_id=paste0(name,'-risk'),version='1',subject_id=paste0(name,'-bond'),currency='EUR',probability_measure='PHYSICAL',horizon=horizon,time_unit='days',conditioning='initially_performing',sampling_design='FIXED_WEIGHTED_SCENARIOS',event='first_default',default_definition='ULTIMATE_CONTRACTUAL_SHORTFALL');records<-list();for(i in seq_along(covered$ending_states)){e<-covered$ending_states[[i]];failed<-e$ultimate_shortfall>0;records[[i]]<-list(scenario_id=e$scenario_id,subject_id=paste0(name,'-bond'),initial_default=FALSE,defaulted=failed,horizon_complete=TRUE,weight=paths$scenario_weights[[i]],ead_at_default=if(failed)e$contractual_claim else 0,economic_loss=if(failed)e$ultimate_shortfall else 0)};risk<-estimate_simulation_risk(records,sampling)$value;target<-sampling[c('event','horizon','time_unit','probability_measure','conditioning','default_definition')];subject<-list(subject_id=paste0(name,'-bond'),subject_type='issue');components<-list(c(list(component_id=paste0(name,'-pd'),quantity='PD',value=risk$pd),subject,list(variant='dual_recourse_ultimate',definition=target)),c(list(component_id=paste0(name,'-el'),quantity='EL',value=risk$expected_loss,currency='EUR'),subject,list(variant='dual_recourse_ultimate',definition=target)));binding<-list(profile_id=name,profile_version='1',model_id=bond$bond_id,model_version=bond$version,model_hash=covered$sha256,input_hash=paths$sha256);assessment<-compose_risk_assessment(paste0(name,'-assessment'),subject,components,binding,origin,origin,origin)$value
 error<-tryCatch({if(name=='maturity_extension'){wrong<-issuer_rows;wrong[[2]]$extension_triggered<-TRUE;covered_bond_dual_recourse(pool,paths,bond,wrong)}else{wrong<-case$pool_input;wrong$eligibility_profile$allowed_asset_classes<-list('AUTO_LOAN');do.call(build_credit_asset_pool,wrong)}},error=identity);stopifnot(inherits(error,'creditratingsystem_error'));errors[[name]]<-error$code;out[[name]]<-list(subjects=subjects,pool=pool,paths=paths,issuer_portfolio=issuer,covered_recourse=covered,account_stress=account,risk=risk,assessment=assessment)
 }
 if(verify_reference){same<-function(a,b)stopifnot(is.finite(a),abs(a-b)<=1e-10+1e-12*abs(b));for(name in names(out)){r<-out[[name]];e<-r$covered_recourse$ending_states;same(e[[1]]$cover_payment,35);same(e[[1]]$ultimate_shortfall,if(name=='maturity_extension')35 else 32.5);same(e[[2]]$issuer_payment,100);same(e[[2]]$ultimate_shortfall,0);same(r$risk$pd,.5);same(r$risk$expected_loss,if(name=='maturity_extension')17.5 else 16.25);same(r$issuer_portfolio$distribution$expected_loss,25);same(r$account_stress$ending_states[[1]]$credit_loss,22.5);stopifnot(r$assessment$composition_status=='CONSISTENT',errors[[name]]==if(name=='maturity_extension')'STRUCTURED_EXTENSION'else'STRUCTURED_ROUTE')};ext<-out$maturity_extension$covered_recourse$ending_states[[1]];stopifnot(ext$extension_activated,ext$effective_maturity=='2024-07-01');same(ext$original_date_principal_deferral_or_shortfall,100)}
 list(data_origin=data$data_origin,version=data$version,product=data$product,variants=out,contract_error_codes=errors)
}
